package com.mycompany.orbitaacademica.controller;
import com.mycompany.orbitaacademica.dao.TursoDAO;import com.mycompany.orbitaacademica.service.PrivateFileService;import jakarta.servlet.http.HttpSession;import org.springframework.core.io.FileSystemResource;import org.springframework.http.*;import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;import java.nio.file.*;import java.util.*;
@Controller public class PrivateDownloadController{private final TursoDAO dao;private final PrivateFileService fs;public PrivateDownloadController(TursoDAO d,PrivateFileService f){dao=d;fs=f;}
@GetMapping("/archivo-privado/{tipo}/{id}") public ResponseEntity<?> download(@PathVariable String tipo,@PathVariable long id,HttpSession s){try{String rol=String.valueOf(s.getAttribute("rol"));String usuario=String.valueOf(s.getAttribute("usuario"));String ref=null;String name="documento";
if("documento".equals(tipo)){var r=dao.consultar("SELECT d.archivo_url,d.nombre_archivo,e.usuario_id FROM DocumentosEstudiante d JOIN Estudiantes e ON e.id=d.estudiante_id WHERE d.id=?",id);if(r.isEmpty())return ResponseEntity.notFound().build();if(!"ADMIN".equals(rol)&&!Objects.equals(String.valueOf(r.get(0).get("usuario_id")),String.valueOf(dao.consultar("SELECT id FROM Usuarios WHERE usuario=?",usuario).get(0).get("id"))))return ResponseEntity.status(403).build();ref=String.valueOf(r.get(0).get("archivo_url"));name=String.valueOf(r.get(0).get("nombre_archivo"));}
else if("pago".equals(tipo)){var r=dao.consultar("SELECT p.comprobante_url,p.nombre_archivo,e.usuario_id FROM PagosCuota p JOIN Estudiantes e ON e.id=p.estudiante_id WHERE p.id=?",id);if(r.isEmpty())return ResponseEntity.notFound().build();if(!"ADMIN".equals(rol)&&!Objects.equals(String.valueOf(r.get(0).get("usuario_id")),String.valueOf(dao.consultar("SELECT id FROM Usuarios WHERE usuario=?",usuario).get(0).get("id"))))return ResponseEntity.status(403).build();ref=String.valueOf(r.get(0).get("comprobante_url"));name=String.valueOf(r.get(0).get("nombre_archivo"));}
else if("foto".equals(tipo)){var r=dao.consultar("SELECT p.foto_url FROM PerfilArchivos p JOIN Usuarios u ON u.id=p.usuario_id WHERE u.usuario=?",usuario);if(r.isEmpty())return ResponseEntity.notFound().build();ref=String.valueOf(r.get(0).get("foto_url"));name="perfil";}
else return ResponseEntity.badRequest().build();Path path=fs.resolve(ref);if(!Files.exists(path))return ResponseEntity.notFound().build();String content=Files.probeContentType(path);return ResponseEntity.ok().contentType(MediaType.parseMediaType(content==null?"application/octet-stream":content)).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.inline().filename(name==null?"archivo":name).build().toString()).body(new FileSystemResource(path));}catch(Exception e){return ResponseEntity.status(404).build();}}
}
